```python
from decimal import Decimal
from operator import index


def round_up(number, digits=0):
    """Round toward positive infinity to the given number of decimal places."""
    digits = index(digits)
    value = Decimal(str(number))
    if not value.is_finite() or value.is_zero():
        return number

    sign, coefficient, exponent = value.as_tuple()
    keep = len(coefficient) + exponent + digits
    if exponent >= -digits or (keep > 0 and not any(coefficient[keep:])):
        return number

    rounded = list(coefficient[:max(0, keep)]) or [0]
    if not sign:
        i = len(rounded) - 1
        while i >= 0 and rounded[i] == 9:
            rounded[i] = 0
            i -= 1
        if i < 0:
            rounded.insert(0, 1)
        else:
            rounded[i] += 1

    result = Decimal((sign, tuple(rounded), -digits))
    if isinstance(number, Decimal):
        return result
    return int(result) if digits <= 0 else float(result)
```

