from math import isqrt


def is_abundant(n: int) -> bool:
    if n <= 1:
        return False

    total = 1
    for divisor in range(2, isqrt(n) + 1):
        if n % divisor == 0:
            partner = n // divisor
            total += divisor
            if partner != divisor:
                total += partner
            if total > n:
                return True
    return False
```

