def mul_even_odd(numbers):
    """Return the product of the first even and first odd numbers."""
    even = odd = None
    for number in numbers:
        if number % 2 == 0:
            if even is None:
                even = number
        elif odd is None:
            odd = number

        if even is not None and odd is not None:
            return even * odd

    raise ValueError("Expected at least one even and one odd number.")
