def find_Extra(arr1, arr2, n):
    if len(arr1) < len(arr2):
        arr1, arr2 = arr2, arr1
    if len(arr1) != len(arr2) + 1:
        raise ValueError("Array lengths must differ by one")

    lo, hi = 0, len(arr2)
    if lo == hi:
        return 0

    while lo < hi:
        mid = (lo + hi) // 2
        if arr1[mid] != arr2[mid]:
            hi = mid
        elif arr1[mid] != arr1[mid + 1]:
            lo = mid + 1
        else:
            # Duplicates can mask an earlier mismatch.
            return next((i for i in range(lo, hi) if arr1[i] != arr2[i]), hi)
    return lo
```

