def max_occurrences(items):
    """Return the most frequent item, breaking ties by first occurrence."""
    if not items:
        raise ValueError("max_occurrences requires a nonempty list")
    try:
        return Counter(items).most_common(1)[0][0]
    except TypeError:
        # Lists and other unhashable items can still be counted by equality.
        return max(items, key=items.count)
