def is_Isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False

    forward = {}
    reverse = {}
    for a, b in zip(s, t):
        if (a in forward and forward[a] != b) or (b in reverse and reverse[b] != a):
            return False
        forward[a] = b
        reverse[b] = a
    return True
```

