from math import isqrt


def smallest_Divisor(n: int) -> int:
    """Return the smallest positive prime divisor of an integer with |n| >= 2."""
    n = abs(n)
    if n < 2:
        raise ValueError("Expected an integer with absolute value at least 2")
    if n % 2 == 0:
        return 2
    for divisor in range(3, isqrt(n) + 1, 2):
        if n % divisor == 0:
            return divisor
    return n
```

