```python
def all_Bits_Set_In_The_Given_Range(n: int, left: int, right: int) -> bool:
    """Check bits from left through right, counting the least significant bit as 1."""
    if n < 0 or min(left, right) < 1:
        raise ValueError("Expected a nonnegative number and positive bit positions.")
    if left > right:
        return True  # An empty range has no unset bits.
    if right > n.bit_length():
        return False
    mask = (1 << (right - left + 1)) - 1
    return ((n >> (left - 1)) & mask) == mask
```

