```python
def get_median(a, b, n):
    if n <= 0 or len(a) != n or len(b) != n:
        raise ValueError("Both lists must have the same positive length n.")

    low, high = 0, n
    while low <= high:
        i = (low + high) // 2
        j = n - i

        if i > 0 and j < n and a[i - 1] > b[j]:
            high = i - 1
        elif j > 0 and i < n and b[j - 1] > a[i]:
            low = i + 1
        else:
            if i == 0:
                return (b[-1] + a[0]) / 2
            if j == 0:
                return (a[-1] + b[0]) / 2
            return (max(a[i - 1], b[j - 1]) + min(a[i], b[j])) / 2
```

