def min_sum_path(triangle):
    if not triangle:
        return 0

    costs = list(triangle[-1])
    for i in range(len(triangle) - 2, -1, -1):
        for j, value in enumerate(triangle[i]):
            costs[j] = value + min(costs[j], costs[j + 1])
    return costs[0]
```

