def is_polite(n: int) -> int:
    """Return the nth positive integer that is not a power of two (1-indexed)."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be positive")

    low, high = 3, 2 * n + 1
    while low < high:
        mid = (low + high) // 2
        # There are mid.bit_length() powers of two from 1 through mid.
        if mid - mid.bit_length() < n:
            low = mid + 1
        else:
            high = mid
    return low
```

