```python
def maximum_segments(n: int, a: int, b: int, c: int) -> int:
    """Return the most segments totaling n exactly, or 0 if impossible."""
    if n < 0 or min(a, b, c) <= 0:
        raise ValueError("n must be nonnegative and segment lengths positive")

    best = [0] + [-1] * n
    for total in range(1, n + 1):
        for length in (a, b, c):
            if length <= total and best[total - length] >= 0:
                best[total] = max(best[total], best[total - length] + 1)

    return max(0, best[n])
```

