def find_closet(a, b, c, n, m, p):
    """Return a triple, one value per sorted prefix, with the smallest range."""
    if not (0 < n <= len(a) and 0 < m <= len(b) and 0 < p <= len(c)):
        raise ValueError("Each prefix length must be positive and within its array.")

    i = j = k = 0
    best = None
    while i < n and j < m and k < p:
        x, y, z = a[i], b[j], c[k]
        low = min(x, y, z)
        span = max(x, y, z) - low
        if best is None or span < best_span:
            best = (x, y, z)
            best_span = span
            if span == 0:
                break

        if x == low:
            i += 1
        elif y == low:
            j += 1
        else:
            k += 1

    return best
```

