def find_triplet_array(arr, n, target):
    n = min(n, len(arr))
    for i in range(n - 2):
        seen = set()
        for j in range(i + 1, n):
            needed = target - arr[i] - arr[j]
            if needed in seen:
                return (arr[i], needed, arr[j])
            seen.add(arr[j])
    return None
```

