import sys

LIMIT = 10**12


def solve(s):
    n = len(s)
    if n < 4:
        return "unlucky"

    # dp[i]: maximum sum for the first i digits with the current part count.
    dp = [-1] * (n + 1)
    dp[0] = 0

    for remaining in (3, 2, 1, 0):
        nxt = [-1] * (n + 1)
        for start, total in enumerate(dp):
            if total < 0:
                continue

            value = 0
            for end in range(start + 1, min(start + 13, n - remaining) + 1):
                value = value * 10 + s[end - 1] - 48
                if value > LIMIT:
                    break
                if n - end <= 13 * remaining:
                    candidate = total + value
                    if candidate > nxt[end]:
                        nxt[end] = candidate
                if value == 0:
                    break  # A single zero is valid, but cannot be extended.
        dp = nxt

    return str(dp[n]) if dp[n] >= 0 else "unlucky"


def main():
    read = sys.stdin.buffer.readline
    cases = int(read())
    sys.stdout.write("\n".join(solve(read().strip()) for _ in range(cases)))


if __name__ == "__main__":
    main()
```

