def min_Jumps(lengths, d):
    steps = tuple(lengths)
    if not steps or any(step <= 0 for step in steps):
        raise ValueError("Jump lengths must be positive.")

    distance = abs(d)
    if distance == 0:
        return 0
    if distance in steps:
        return 1

    longest = max(steps)
    if distance < longest:
        return 2
    return (distance + longest - 1) / longest
```

