def coin_change(coins, m, amount):
    if amount < 0:
        return 0
    if not 0 <= m <= len(coins):
        raise ValueError("m must be between 0 and the number of coins")

    ways = [0] * (amount + 1)
    ways[0] = 1
    for coin in set(coins[:m]):
        if coin <= 0:
            raise ValueError("coin denominations must be positive")
        for total in range(coin, amount + 1):
            ways[total] += ways[total - coin]
    return ways[amount]
```

