def remove_parenthesis(text):
    if not isinstance(text, str):
        text = " ".join(text)

    result = []
    openings = []
    for char in text:
        if char == "(":
            openings.append(len(result))
        elif char == ")" and openings:
            del result[openings.pop():]
            continue
        result.append(char)

    return " ".join("".join(result).split())
