import heapq


def nth_super_ugly_number(n, primes):
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")

    factors = set(primes)
    if any(not isinstance(p, int) or p < 2 for p in factors):
        raise ValueError("factors must be integers greater than 1")
    if n == 1:
        return 1
    if not factors:
        raise ValueError("at least one prime is required for n > 1")

    numbers = [1]
    heap = [(p, p, 0) for p in factors]
    heapq.heapify(heap)

    while len(numbers) < n:
        value = heap[0][0]
        numbers.append(value)
        while heap[0][0] == value:
            _, p, i = heap[0]
            heapq.heapreplace(heap, (p * numbers[i + 1], p, i + 1))

    return numbers[-1]
```

