def sum_Square(n: int) -> bool:
    if n < 0:
        return False

    a, b = 0, isqrt(n)
    while a <= b:
        total = a * a + b * b
        if total == n:
            return True
        if total < n:
            a += 1
        else:
            b -= 1
    return False
```

