def largest_subset(numbers):
    # Sort by magnitude, with zeros last since every nonzero integer divides zero.
    values = sorted(map(abs, numbers), key=lambda n: (n == 0, n))
    lengths = [1] * len(values)

    for i, value in enumerate(values):
        for j in range(i):
            divisor = values[j]
            if value == divisor or (divisor != 0 and value % divisor == 0):
                lengths[i] = max(lengths[i], lengths[j] + 1)

    return max(lengths, default=0)
```

