import sys
from decimal import Decimal, localcontext


def floor_sum(n, m, a, b):
    # Sum of (a*i + b) // m for 0 <= i < n.
    total = 0
    while True:
        q, a = divmod(a, m)
        total += q * n * (n - 1) // 2
        q, b = divmod(b, m)
        total += q * n
        top = a * n + b
        if top < m:
            return total
        n, b = divmod(top, m)
        m, a = a, m


def scaled_logs(x, y, digits):
    with localcontext() as ctx:
        ctx.prec = digits + 20
        return tuple(int(Decimal(v).log10().scaleb(digits))
                     for v in (x, y, y + 1))


def strip_zeros(n):
    while n % 10 == 0:
        n //= 10
    return n


def exact_floor(x, z, e, scale, a, b):
    # floor(log10(x**e / z)), including exact powers of ten.
    digits = 50
    while True:
        low = (e * (a - 1) - (b + 2)) // scale
        high = (e * (a + 2) - (b - 1)) // scale
        if low == high:
            return low

        u, v = strip_zeros(x), strip_zeros(z)
        if e <= v.bit_length() and u ** e == v:
            return e * (len(str(x)) - len(str(u))) - (len(str(z)) - len(str(v)))

        digits *= 2
        scale = 10 ** digits
        with localcontext() as ctx:
            ctx.prec = digits + 20
            a = int(Decimal(x).log10().scaleb(digits))
            b = int(Decimal(z).log10().scaleb(digits))


def solve(x, y):
    start, power = 1, x
    while power < y:
        power *= x
        start += 1

    scale = 10 ** 50
    a, b, c = scaled_logs(x, y, 50)

    def possible(left, right):
        # Upper bound on the number of prefix matches in [left, right].
        n = right - left + 1
        upper = floor_sum(n, scale, a + 2, left * (a + 2) - (b - 1))
        lower = floor_sum(n, scale, a - 1, left * (a - 1) - (c + 2))
        return upper > lower

    end = start
    while True:
        if possible(start, end):
            lo, hi = start, end
            while lo < hi:
                mid = (lo + hi) // 2
                if possible(lo, mid):
                    hi = mid
                else:
                    lo = mid + 1
            e = lo
            if (exact_floor(x, y, e, scale, a, b) >
                    exact_floor(x, y + 1, e, scale, a, c)):
                return e
            start = e + 1
        else:
            start = end + 1
        if start > end:
            end *= 2


def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    cases = next(data)
    print("\n".join(f"Case {i}: {solve(next(data), next(data))}"
                    for i in range(1, cases + 1)))


if __name__ == "__main__":
    main()
```

