def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    t = next(data)
    output = []

    for _ in range(t):
        n, m = next(data), next(data)
        a = {next(data) for _ in range(n)}
        match = None
        for _ in range(m):
            x = next(data)
            if match is None and x in a:
                match = x

        if match is None:
            output.append("NO")
        else:
            output.extend(("YES", f"1 {match}"))

    print("\n".join(output))

if __name__ == "__main__":
