def min_jumps(arr, n):
    """Return the fewest jumps across the first n elements, or -1 if unreachable."""
    if not 0 <= n <= len(arr):
        raise ValueError("n must be between 0 and len(arr)")
    if n <= 1:
        return 0

    jumps = end = farthest = 0
    for i in range(n - 1):
        farthest = max(farthest, i + arr[i])
        if i == end:
            if farthest == end:
                return -1
            jumps += 1
            end = farthest
            if end >= n - 1:
                return jumps
    return -1
```

