def max_sub_array_sum(arr, n):
    """Return the longest length among maximum-sum subarrays of arr[:n]."""
    n = min(n, len(arr))
    if n <= 0:
        return 0

    current_sum = best_sum = arr[0]
    current_len = best_len = 1

    for i in range(1, n):
        if current_sum < 0:
            current_sum, current_len = arr[i], 1
        else:
            current_sum += arr[i]
            current_len += 1

        if (current_sum, current_len) > (best_sum, best_len):
            best_sum, best_len = current_sum, current_len

    return best_len
```

