def lcs_of_three(a: str, b: str, c: str) -> int:
    a, b, c = sorted((a, b, c), key=len, reverse=True)
    if not c:
        return 0

    rows, cols = len(b) + 1, len(c) + 1
    prev = [[0] * cols for _ in range(rows)]

    for x in a:
        curr = [[0] * cols for _ in range(rows)]
        for j, y in enumerate(b, 1):
            for k, z in enumerate(c, 1):
                if x == y == z:
                    curr[j][k] = prev[j - 1][k - 1] + 1
                else:
                    curr[j][k] = max(prev[j][k], curr[j - 1][k], curr[j][k - 1])
        prev = curr

    return prev[-1][-1]
```

