import sys


def main():
    read = sys.stdin.buffer.readline
    n, m = map(int, read().split())
    limit = 10**9
    size = 4 * n + 4
    mx = [limit] * size
    add = [0] * size
    cap = [None] * size

    def shift(p, x):
        mx[p] += x
        add[p] += x
        if cap[p] is not None:
            cap[p] += x

    def clamp(p, x):
        if mx[p] > x:
            mx[p] = cap[p] = x

    def push(p):
        left = p * 2
        if add[p]:
            shift(left, add[p])
            shift(left + 1, add[p])
            add[p] = 0
        if cap[p] is not None:
            clamp(left, cap[p])
            clamp(left + 1, cap[p])
            cap[p] = None

    def update(p, lo, hi, l, r, t, x):
        if l <= lo and hi <= r:
            if t == 1:
                shift(p, x)
            else:
                clamp(p, x)
            return
        push(p)
        mid = (lo + hi) // 2
        if l <= mid:
            update(p * 2, lo, mid, l, r, t, x)
        if r > mid:
            update(p * 2 + 1, mid + 1, hi, l, r, t, x)
        mx[p] = max(mx[p * 2], mx[p * 2 + 1])

    def maximum(p, lo, hi, l, r):
        if l <= lo and hi <= r:
            return mx[p]
        push(p)
        mid = (lo + hi) // 2
        if r <= mid:
            return maximum(p * 2, lo, mid, l, r)
        if l > mid:
            return maximum(p * 2 + 1, mid + 1, hi, l, r)
        return max(maximum(p * 2, lo, mid, l, r),
                   maximum(p * 2 + 1, mid + 1, hi, l, r))

    # Propagate the largest possible values, imposing each recorded upper bound.
    ops = []
    for _ in range(m):
        t, l, r, x = map(int, read().split())
        ops.append((t, l, r, x))
        update(1, 1, n, l, r, t, x)

    # Undo additions to test the resulting candidate at each query time.
    for t, l, r, x in reversed(ops):
        if t == 1:
            update(1, 1, n, l, r, 1, -x)
        elif maximum(1, 1, n, l, r) != x:
            print("NO")
            return

    ans = [maximum(1, 1, n, i, i) for i in range(1, n + 1)]
    if min(ans) < -limit:
        print("NO")
    else:
        print("YES")
        print(*ans)


if __name__ == "__main__":
    main()
```

