def previous_palindrome(n: int) -> int:
    if n <= 0:
        raise ValueError("No nonnegative palindrome is smaller than n.")

    digits = str(n)
    length = len(digits)
    prefix = digits[: (length + 1) // 2]

    def mirror(left):
        right = left[:-1] if length % 2 else left
        return int(left + right[::-1])

    candidate = mirror(prefix)
    if candidate < n:
        return candidate

    smaller = str(int(prefix) - 1)
    if smaller == "0" or len(smaller) < len(prefix):
        return 10 ** (length - 1) - 1
    return mirror(smaller)
```

