import sys
from collections import deque


def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    m, n = next(data), next(data)
    board = [[next(data) for _ in range(n)] for _ in range(m)]

    rectangles = []
    for left in range(n):
        for right in range(left, n):
            row_mask = ((1 << (right - left + 1)) - 1) << left
            for top in range(m):
                mask = 0
                for bottom in range(top, m):
                    mask |= row_mask << (bottom * n)
                    if top != bottom or left != right:
                        rectangles.append(mask)

    best = float("inf")
    for r in range(m - 1):
        for c in range(n - 1):
            start = (board[r][c] | (board[r][c + 1] << 1) |
                     (board[r + 1][c] << 2) | (board[r + 1][c + 1] << 3))
            if start == 15:
                print(0)
                return

            # For this target, only the rectangle's overlap with it matters.
            pos = r * n + c
            flips = {((mask >> pos) & 3) | (((mask >> (pos + n)) & 3) << 2)
                     for mask in rectangles}
            queue = deque([(start, 0)])
            seen = {start}
            while queue:
                state, dist = queue.popleft()
                if state == 15:
                    best = min(best, dist)
                    break
                if dist + 1 >= best:
                    continue
                for flip in flips:
                    nxt = state ^ flip
                    if nxt not in seen:
                        seen.add(nxt)
                        queue.append((nxt, dist + 1))

    print(-1 if best == float("inf") else best)


if __name__ == "__main__":
    main()
