def super_seq(str1, str2, m, n):
    if n > m:
        str1, str2, m, n = str2, str1, n, m

    dp = list(range(n + 1))
    for i in range(1, m + 1):
        diagonal, dp[0] = dp[0], i
        for j in range(1, n + 1):
            above = dp[j]
            if str1[i - 1] == str2[j - 1]:
                dp[j] = diagonal + 1
            else:
                dp[j] = 1 + min(above, dp[j - 1])
            diagonal = above
    return dp[n]
