import sys


def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    n, m = next(data), next(data)
    parents = {}

    def find(parent, v):
        while v != parent[v]:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v

    for _ in range(m):
        a, b, color = next(data), next(data), next(data)
        if color not in parents:
            parents[color] = list(range(n + 1))
        parent = parents[color]
        parent[find(parent, a)] = find(parent, b)

    components = [
        [find(parent, v) for v in range(n + 1)]
        for parent in parents.values()
    ]

    answers = []
    for _ in range(next(data)):
        u, v = next(data), next(data)
        answers.append(str(sum(comp[u] == comp[v] for comp in components)))
    print("\n".join(answers))


if __name__ == "__main__":
