def solve(first, second):
    diff = [0] * 26
    for line, sign in ((first, 1), (second, -1)):
        for ch in line.lower():
            if 97 <= ch <= 122:
                diff[ch - 97] += sign

    if not any(diff):
        return "YES"
    if min(diff) < 0 < max(diff):
        return "NO LUCK"

    half = []
    middle = ""
    for i, count in enumerate(diff):
        count = abs(count)
        letter = chr(97 + i)
        if count % 2:
            if middle:
                return "NO LUCK"
            middle = letter
        half.append(letter * (count // 2))

    left = "".join(half)
    return left + middle + left[::-1]


def main():
