import sys


def main():
    read = sys.stdin.buffer.readline
    n = int(read())
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for _ in range(int(read())):
        u, v = map(int, read().split())
        a, b = find(u), find(v)
        if a != b:
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]

    component = [find(i) for i in range(n + 1)]
    for _ in range(int(read())):
        u, v = map(int, read().split())
        if component[u] == component[v]:
            size[component[u]] = 0

    print(max(size[component[i]] for i in range(1, n + 1)))


if __name__ == "__main__":
    main()
```

