import sys

def main():
    read = sys.stdin.buffer.readline
    n = int(read())
    groups = [[] for _ in range(4)]
    doubled = set()

    for _ in range(n):
        x, y = map(int, read().split())
        # Pairwise y-coordinate sums fit in the lower 12 bits.
        key = ((x + 1000) << 12) + (y + 1000)
        doubled.add(2 * key)
        groups[2 * (x & 1) + (y & 1)].append(key)

    answer = 0
    for group in groups:
        for i, a in enumerate(group):
            for c in group[:i]:
                if a + c in doubled:
                    answer += 1
    print(answer)

if __name__ == "__main__":
    main()
```

