import sys

def main():
    n, p = map(int, sys.stdin.buffer.readline().split())
    s = bytearray(sys.stdin.buffer.readline().strip())
    limit = ord('a') + p

    def valid(i, c):
        return (i < 1 or c != s[i - 1]) and (i < 2 or c != s[i - 2])

    for i in range(n - 1, -1, -1):
        for c in range(s[i] + 1, limit):
            if not valid(i, c):
                continue
            s[i] = c
            for j in range(i + 1, n):
                for d in range(ord('a'), limit):
                    if valid(j, d):
                        s[j] = d
                        break
            print(s.decode())
            return
    print("NO")

if __name__ == "__main__":
    main()
```

